  ('21dd5914-83eb-587f-85b1-d3d489ce3a7a', 'f9a044d3-073d-5abf-b697-0f8d5f32b6e1', 'Lab 3: Singly Linked Lists', '## Lab 3: Singly Linked Lists
INSERT INTO practical_drafts (practical_id, student_id, files, updated_at) VALUES
  ('96452ec1-9b97-57b6-8ccf-00ce1a5a84af', '2f0b2c4f-4119-59d7-a017-20e4c0a12fbb', '{"main.py": "class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\n\nclass BST:\n    \"\"\"Binary Search Tree that stores unique integer keys.\"\"\"\n\n    def __init__(self):\n        self.root = None\n        self._size = 0\n\n    def insert(self, key):\n        \"\"\"Insert key into the tree.\"\"\"\n        if self.root is None:\n            self.root = Node(key)\n            self._size += 1\n            return\n        node = self.root\n        while True:\n            if key < node.key:\n                if node.left is None:\n                    node.left = Node(key)\n                    self._size += 1\n                    return\n                node = node.left\n            else:\n                if node.right is None:\n                    node.right = Node(key)\n                    self._size += 1\n                    return\n                node = node.right\n\n    def search(self, key):\n        \"\"\"Return True if key is present.\"\"\"\n        node = self.root\n        while node:\n            if key == node.key:\n                return True\n            node = node.left if key < node.key else node.right\n        return False\n\n    def inorder(self):\n        \"\"\"Return keys in ascending order.\"\"\"\n        out = []\n\n        def walk(node):\n            if node:\n                walk(node.left)\n                out.append(node.key)\n                walk(node.right)\n\n        walk(self.root)\n        return out\n\n    def min(self):\n        node = self.root\n        if node is None:\n            return None\n        while node.left:\n            node = node.left\n        return node.key\n\n    def max(self):\n        node = self.root\n        if node is None:\n            return None\n        while node.right:\n            node = node.right\n        return node.key\n\n    def height(self):\n        def h(node):\n            if node is None:\n                return 0\n            return 1 + max(h(node.left), h(node.right))\n\n        return h(self.root)\n\n    def __len__(self):\n        return self._size\n\n\nif __name__ == \"__main__\":\n    tree = BST()\n    for k in [50, 30, 70, 20, 40, 60, 80, 50]:\n        tree.insert(k)\n    print(\"Inorder:\", tree.inorder())\n    print(\"Size:\", len(tree), \"Height:\", tree.height())\n"}'::jsonb, now() - interval '72000 seconds')
INSERT INTO submissions (id, practical_id, student_id, files, status, tests_passed, tests_total, test_results, rubric_score, max_score, rubric_breakdown, ai_feedback, grading_model, faculty_score, faculty_comment, integrity, submitted_at, graded_at, reviewed_at) VALUES
  ('657ae1de-f1aa-5dc3-ae16-35f7a2423793', '21dd5914-83eb-587f-85b1-d3d489ce3a7a', '2f0b2c4f-4119-59d7-a017-20e4c0a12fbb', '{"main.py": "class Node:\n    def __init__(self, value, next=None):\n        self.value = value\n        self.next = next\n\n\nclass LinkedList:\n    \"\"\"Singly linked list.\"\"\"\n\n    def __init__(self):\n        self.head = None\n        self._size = 0\n\n    def append(self, value):\n        node = Node(value)\n        if self.head is None:\n            self.head = node\n        else:\n            cur = self.head\n            while cur.next:\n                cur = cur.next\n            cur.next = node\n        self._size += 1\n\n    def prepend(self, value):\n        self.head = Node(value, self.head)\n        self._size += 1\n\n    def delete(self, value):\n        prev, cur = None, self.head\n        while cur:\n            if cur.value == value:\n                if prev is None:\n                    self.head = cur.next\n                else:\n                    prev.next = cur.next\n                self._size -= 1\n                return True\n            prev, cur = cur, cur.next\n        return False\n\n    def reverse(self):\n        prev, cur = None, self.head\n        while cur:\n            cur.next, prev, cur = prev, cur, cur.next\n        self.head = prev\n\n    def to_list(self):\n        out, cur = [], self.head\n        while cur:\n            out.append(cur.value)\n            cur = cur.next\n        return out\n\n    def __len__(self):\n        return self._size\n"}'::jsonb, 'graded', 7, 7, '[{"name": "test_append_and_to_list", "passed": true, "message": null, "hidden": false}, {"name": "test_prepend", "passed": true, "message": null, "hidden": false}, {"name": "test_delete_middle", "passed": true, "message": null, "hidden": false}, {"name": "test_delete_missing", "passed": true, "message": null, "hidden": false}, {"name": "test_reverse", "passed": true, "message": null, "hidden": false}, {"name": "test_delete_head", "passed": true, "message": null, "hidden": true}, {"name": "test_reverse_empty", "passed": true, "message": null, "hidden": true}]'::jsonb, 9.5, 10.0, '[{"criterion_id": "correctness", "name": "Correctness", "score": 6.0, "max_points": 6.0, "feedback": "Meets expectations."}, {"criterion_id": "edge_cases", "name": "Edge cases", "score": 2.0, "max_points": 2.0, "feedback": "Meets expectations."}, {"criterion_id": "code_quality", "name": "Code quality", "score": 1.5, "max_points": 2.0, "feedback": "Partially meets expectations."}]'::jsonb, 'Well-structured linked list with clear pointer manipulation.', 'synthetic-seed', NULL, NULL, '{"risk_level": "low", "risk_score": 0, "ai_likelihood": 0, "summary": "No integrity concerns: the code was written in the proctored editor and shows no strong AI-generation hallmarks.", "signals": [], "proctoring": {"proctored": true, "sessions": 1, "paste_blocked": 0, "copy_blocked": 0, "focus_lost": 0, "time_away_ms": 0, "fullscreen_exits": 0, "devtools_blocked": 0, "large_insertions": 0, "typed_chars": 839, "new_code_chars": 497, "typed_ratio": 1.69, "max_burst_cps": 5.7}, "content": {"ai_style_score": 0, "indicators": [], "model": "rules", "source": "fallback"}, "similarity": {"max_peer_similarity": 0.0, "peer_submission_id": null, "peer_student_name": null}, "analyzed_at": "2026-11-13T18:47:25.047603Z"}'::jsonb, now() - interval '583615 seconds', now() - interval '583611 seconds', NULL),
