  ('7934a0d8-ee29-5791-867e-f273cf387513', '96452ec1-9b97-57b6-8ccf-00ce1a5a84af', '9658b9dc-fa8a-59a1-9b32-cd94d43d04f7', '{"main.py": "from typing import List, Optional\n\n\nclass Node:\n    \"\"\"A node in the binary search tree.\"\"\"\n\n    def __init__(self, key: int) -> None:\n        self.key: int = key\n        self.left: Optional[\"Node\"] = None\n        self.right: Optional[\"Node\"] = None\n\n\nclass BST:\n    \"\"\"Binary Search Tree implementation that stores unique integer keys.\n\n    Time complexity: O(h) for insert and search, where h is the height of the tree.\n    \"\"\"\n\n    def __init__(self) -> None:\n        self.root: Optional[Node] = None\n        self._size: int = 0\n\n    def insert(self, key: int) -> None:\n        \"\"\"Insert a key into the BST, ignoring duplicates.\n\n        Args:\n            key: The integer key to insert.\n\n        Returns:\n            None\n        \"\"\"\n        # Edge case: empty tree — the new node becomes the root\n        if self.root is None:\n            self.root = Node(key)\n            self._size += 1\n            return\n        current = self.root\n        while True:\n            # Step 1: smaller keys go to the left subtree\n            if key < current.key:\n                if current.left is None:\n                    current.left = Node(key)\n                    self._size += 1\n                    return\n                current = current.left\n            # Step 2: larger keys go to the right subtree\n            elif key > current.key:\n                if current.right is None:\n                    current.right = Node(key)\n                    self._size += 1\n                    return\n                current = current.right\n            # Step 3: duplicate key — nothing to do\n            else:\n                return\n\n    def search(self, key: int) -> bool:\n        \"\"\"Search for a key in the BST.\n\n        Args:\n            key: The key to look for.\n\n        Returns:\n            True if the key exists, otherwise False.\n        \"\"\"\n        current = self.root\n        while current is not None:\n            if key == current.key:\n                return True\n            current = current.left if key < current.key else current.right\n        return False\n\n    def inorder(self) -> List[int]:\n        \"\"\"Return all keys in ascending order using an iterative in-order traversal.\"\"\"\n        result: List[int] = []\n        stack: List[Node] = []\n        current = self.root\n        while stack or current is not None:\n            while current is not None:\n                stack.append(current)\n                current = current.left\n            current = stack.pop()\n            result.append(current.key)\n            current = current.right\n        return result\n\n    def min(self) -> Optional[int]:\n        \"\"\"Return the minimum key, or None if the tree is empty.\"\"\"\n        if self.root is None:\n            return None\n        current = self.root\n        while current.left is not None:\n            current = current.left\n        return current.key\n\n    def max(self) -> Optional[int]:\n        \"\"\"Return the maximum key, or None if the tree is empty.\"\"\"\n        if self.root is None:\n            return None\n        current = self.root\n        while current.right is not None:\n            current = current.right\n        return current.key\n\n    def height(self) -> int:\n        \"\"\"Return the height of the tree — the number of nodes on the longest root-to-leaf path.\"\"\"\n\n        def _height(node: Optional[Node]) -> int:\n            # Base case: an empty subtree has height 0\n            if node is None:\n                return 0\n            return 1 + max(_height(node.left), _height(node.right))\n\n        return _height(self.root)\n\n    def __len__(self) -> int:\n        \"\"\"Return the number of keys stored in the tree.\"\"\"\n        return self._size\n"}'::jsonb, 'graded', 7, 7, '[{"name": "test_insert_and_search", "passed": true, "message": null, "hidden": false}, {"name": "test_inorder_traversal", "passed": true, "message": null, "hidden": false}, {"name": "test_min_max", "passed": true, "message": null, "hidden": false}, {"name": "test_height", "passed": true, "message": null, "hidden": false}, {"name": "test_duplicate_keys", "passed": true, "message": null, "hidden": false}, {"name": "test_skewed_tree", "passed": true, "message": null, "hidden": true}, {"name": "test_single_negative_key", "passed": true, "message": null, "hidden": true}]'::jsonb, 9.0, 10.0, '[{"criterion_id": "correctness", "name": "Correctness", "score": 5.0, "max_points": 5.0, "feedback": "Meets expectations."}, {"criterion_id": "edge_cases", "name": "Edge cases", "score": 2.0, "max_points": 2.0, "feedback": "Meets expectations."}, {"criterion_id": "code_quality", "name": "Code quality", "score": 1.0, "max_points": 2.0, "feedback": "Partially meets expectations."}, {"criterion_id": "efficiency", "name": "Efficiency", "score": 1.0, "max_points": 1.0, "feedback": "Partially meets expectations."}]'::jsonb, 'Clean BST implementation with correct traversal and min/max logic.', 'synthetic-seed', NULL, NULL, '{"risk_level": "high", "risk_score": 100, "ai_likelihood": 86, "summary": "7 concern(s): Code appeared without being typed; AI-style code patterns; Bulk code insertion. Review the evidence and discuss with the student before taking action.", "signals": [{"key": "typed_ratio", "label": "Code appeared without being typed", "detail": "Only 261 characters were typed in the editor, but the submission adds 2180 new characters (12%).", "severity": "critical", "weight": 35}, {"key": "ai_style", "label": "AI-style code patterns", "detail": "Type hints on 10/10 functions — not used in the starter or the student''s earlier code; 4 structured docstring sections (Args/Returns) typical of generated code; 5 narrative comments (e.g. ''Step 1'', ''Edge case'', ''Time complexity'')", "severit