  ('31ad724e-b02a-555f-ba0b-37a6fec892e2', '96452ec1-9b97-57b6-8ccf-00ce1a5a84af', '9f2ff588-19df-505c-a59b-b6adbccd06e6', '{"main.py": "class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\n\nclass BST:\n    \"\"\"Binary Search Tree that stores unique integer keys.\"\"\"\n\n    def __init__(self):\n        self.root = None\n        self._size = 0\n\n    def insert(self, key):\n        \"\"\"Insert key into the tree.\"\"\"\n        if self.root is None:\n            self.root = Node(key)\n            self._size += 1\n            return\n        node = self.root\n        while True:\n            if key < node.key:\n                if node.left is None:\n                    node.left = Node(key)\n                    self._size += 1\n                    return\n                node = node.left\n            else:\n                if node.right is None:\n                    node.right = Node(key)\n                    self._size += 1\n                    return\n                node = node.right\n\n    def search(self, key):\n        \"\"\"Return True if key is present.\"\"\"\n        node = self.root\n        while node:\n            if key == node.key:\n                return True\n            node = node.left if key < node.key else node.right\n        return False\n\n    def inorder(self):\n        \"\"\"Return keys in ascending order.\"\"\"\n        out = []\n\n        def walk(node):\n            if node:\n                walk(node.left)\n                out.append(node.key)\n                walk(node.right)\n\n        walk(self.root)\n        return out\n\n    def min(self):\n        node = self.root\n        if node is None:\n            return None\n        while node.left:\n            node = node.left\n        return node.key\n\n    def max(self):\n        node = self.root\n        if node is None:\n            return None\n        while node.right:\n            node = node.right\n        return node.key\n\n    def height(self):\n        def h(node):\n            if node is None:\n                return 0\n            return 1 + max(h(node.left), h(node.right))\n\n        return h(self.root)\n\n    def __len__(self):\n        return self._size\n\n\nif __name__ == \"__main__\":\n    tree = BST()\n    for k in [50, 30, 70, 20, 40, 60, 80, 50]:\n        tree.insert(k)\n    print(\"Inorder:\", tree.inorder())\n    print(\"Size:\", len(tree), \"Height:\", tree.height())\n"}'::jsonb, 'graded', 5, 7, '[{"name": "test_insert_and_search", "passed": false, "message": "AssertionError: assertion failed", "hidden": false}, {"name": "test_inorder_traversal", "passed": true, "message": null, "hidden": false}, {"name": "test_min_max", "passed": true, "message": null, "hidden": false}, {"name": "test_height", "passed": true, "message": null, "hidden": false}, {"name": "test_duplicate_keys", "passed": false, "message": "AssertionError: Duplicate keys are inserted again instead of being ignored — revisit the equality case in insert().", "hidden": false}, {"name": "test_skewed_tree", "passed": true, "message": null, "hidden": true}, {"name": "test_single_negative_key", "passed": true, "message": null, "hidden": true}]'::jsonb, 6.0, 10.0, '[{"criterion_id": "correctness", "name": "Correctness", "score": 3.5, "max_points": 5.0, "feedback": "Partially meets expectations."}, {"criterion_id": "edge_cases", "name": "Edge cases", "score": 1.0, "max_points": 2.0, "feedback": "Partially meets expectations."}, {"criterion_id": "code_quality", "name": "Code quality", "score": 1.0, "max_points": 2.0, "feedback": "Needs work."}, {"criterion_id": "efficiency", "name": "Efficiency", "score": 0.5, "max_points": 1.0, "feedback": "Needs work."}]'::jsonb, 'Clean BST implementation. test_insert_and_search fails. Duplicate keys are inserted again instead of being ignored — revisit the equality case in insert().', 'synthetic-seed', NULL, NULL, '{"risk_level": "low", "risk_score": 7, "ai_likelihood