  ('90db3103-0bf9-5b20-b6a4-fe46f4ac4775', '06975ad5-19a7-5bee-80e7-503033ce127c', 'Lab 1: Ohm''s Law — V–I Characteristic', '## Lab 1: Ohm''s Law — V–I Characteristic

**Aim.** Verify Ohm''s law for an unknown resistor Rₓ and find its resistance from the V–I graph.

**Circuit.** A variable DC supply drives Rₓ. An ammeter in series reads the current *I* (mA) and a voltmeter across
Rₓ reads the voltage *V*. The resistor is rated **0.5 W**: watch for it overheating at high voltages.

**Procedure** (in the **Worksheet** tab)
1. Switch the supply on and set a voltage with the knob. Read both meters.
2. Press **Record reading** to copy V and I into the observation table. Take **at least 5 readings** spread over
   **4 V or more**.
3. Fill in R = V / I for each row (careful with units: I is in mA). The V–I graph draws itself.
4. Find R from the slope of the graph, then answer the power questions.

Press **Check** at any time to see which parts are right.
', 'worksheet', 'worksheet', '{"answers.json": "{\"steps\": {}, \"rows\": []}"}'::jsonb, '[{"name": "test_readings", "description": "At least 5 readings at different voltages, spread over 4 V or more.", "hidden": false, "code": "readings(5)\nV = column(\"V\", \"Voltage\")\nI = column(\"I\", \"Current\")\nassert all(i > 0 for i in I), \"Every reading needs a current above 0 mA. Switch the supply on before recording\"\nassert len(set(round(v, 1) for v in V)) >= 5, \"Take readings at 5 different supply voltages\"\nassert max(V) - min(V) >= 4 - 1e-9, \"Spread your readings over at least 4 V\"", "inputs": null, "expected": null}, {"name": "test_r_column", "description": "R = V / I is correct for every reading.", "hidden": false, "code": "V = column(\"V\", \"Voltage\")\nI = column(\"I\", \"Current\")\nR = column(\"R\", \"R = V / I\")\nfor k, (r, v, i) in enumerate(zip(R, V, I)):\n    if i > 0 and near_rel(r, v / i, 0.01):\n        raise AssertionError(\"Reading %d: you divided by the current in mA. Convert I to amperes first\" % (k + 1))\n    assert i > 0 and near_rel(r, v / (i / 1000), 0.01), \"Reading %d: R should be V divided by I\" % (k + 1)", "inputs": null, "expected": null}, {"name": "test_r_from_graph", "description": "R from the slope of your V–I graph.", "hidden": false, "code": "m, _ = fit_line([i / 1000 for i in column(\"I\", \"Current\")], column(\"V\", \"Voltage\"))\nr = answer(\"r_graph\", \"R from the graph\")\nif near_rel(r, m / 1000, 0.03):\n    raise AssertionError(\"Your slope is in volts per milliampere (kΩ). Convert it to ohms\")\nassert near_rel(r, m, 0.03), \"R is the slope of your V–I graph: change in V / change in I, with I in amperes\"", "inputs": null, "expected": null}, {"name": "test_r_mean", "description": "Mean of the R column.", "hidden": false, "code": "R = column(\"R\", \"R = V / I\")\nr = answer(\"r_mean\", \"Mean resistance\")\nassert near_rel(r, sum(R) / len(R), 0.005), \"Add up your R column and divide by the number of readings\"", "inputs": null, "expected": null}, {"name": "test_power", "description": "Power at 9 V.", "hidden": false, "code": "r = answer(\"r_graph\", \"R from the graph\")\np = answer(\"p_9v\", \"Power at 9 V\")\nassert near_rel(p, 81 / r, 0.02), \"Use P = V² / R with V = 9 V and your R from the graph (P is in watts)\"", "inputs": null, "expected": null}, {"name": "test_max_voltage", "description": "Highest safe voltage for a 0.5 W rating.", "hidden": false, "code": "r = answer(\"r_graph\", \"R from the graph\")\nv = answer(\"v_max\", \"Highest safe voltage\")\nassert near_rel(v, math.sqrt(0.5 * r), 0.02), \"Start from P = V² / R with P = 0.5 W and rearrange for V\"", "inputs": null, "expected": null}, {"name": "test_readings_genuine", "description": "Readings come from the bench meters.", "hidden": true, "code": "for k, (v, i) in enumerate(zip(column(\"V\"), column(\"I\"))):\n    assert near_rel(i, v / 220.0 * 1000, 0.03), \"Reading %d does not match the bench meters\" % (k + 1)", "inputs": null, "expected": null}, {"name": "test_r_accuracy", "description": "R is within 3% of the resistor''s true value.", "hidden": true, "code": "assert near_rel(answer(\"r_graph\"), 220.0, 0.03), \"R is more than 3% away from the resistor''s true value\"", "inputs": null, "expected": null}]'::jsonb, '[{"id": "correctness", "name": "Calculations and result", "description": "Every calculated column and step is correct.", "max_points": 6.0}, {"id": "observations", "name": "Observations", "description": "At least five readings over a good range, taken from the apparatus.", "max_points": 2.0}, {"id": "precision", "name": "Units and precision", "description": "Values are given with sensible precision.", "max_points": 2.0}]'::jsonb, 10.0, now() + interval '453600 seconds', 'published', true, 'off', NULL, NULL, '{"kind": "experiment", "apparatus": "dc_bench", "apparatus_config": {"resistance_ohm": 220.0, "rated_power_w": 0.5, "max_voltage_v": 12.0}, "table": {"title": "Observation table", "columns": [{"key": "V", "label": "Voltage V", "unit": "V", "source": "apparatus", "test": null}, {"key": "I", "label": "Current I", "unit": "mA", "source": "apparatus", "test": null}, {"key": "R", "label": "R = V / I", "unit": "Ω", "source": "student", "test": "test_r_column"}], "min_rows": 5, "max_rows": 10, "test": "test_readings"}, "graph": {"title": "V against I", "x": "I", "y": "V", "x_label": "I (mA)", "y_label": "V (V)"}, "sections": [{"id": "analysis", "title": "Calculations", "body": "The slope of the V–I graph is the resistance. Take care with units: the graph''s current axis is in mA.", "visual": null, "steps": [{"id": "r_graph", "label": "R from the slope of the V–I graph", "unit": "Ω", "placeholder": "", "test": "test_r_from_graph"}, {"id": "r_mean", "label": "Mean of your R = V / I column", "unit": "Ω", "placeholder": "", "test": "test_r_mean"}, {"id": "p_9v", "label": "Power dissipated at 9 V, P = V² / R (use R from the graph)", "unit": "W", "placeholder": "", "test": "test_power"}, {"id": "v_max", "label": "Highest safe voltage for this 0.5 W resistor", "unit": "V", "placeholder": "", "test": "test_max_voltage"}]}]}'::jsonb, 'b949c059-a4a0-58d0-b784-b688bfc019f0', now() - interval '432000 seconds', now() - interval '432000 seconds'),
  ('5234ed83-5459-5701-9dd1-08d1311df15a', 'c86c8dcd-86a7-5551-99d6-9cba493f51a0', 'Lab 2: Newton–Raphson and Simpson''s Rule', '## Lab 2: Newton–Raphson and Simpson''s Rule

