', 'worksheet', 'worksheet', '{"answers.json": "{\"steps\": {}, \"rows\": []}"}'::jsonb, '[{"name": "test_nr_f_x0", "description": "Step 1: f(x₀)", "hidden": false, "code": "assert near(answer(''nr_f0'', ''f(x₀)''), -1.0, 1e-06), ''Not quite. Substitute x₀ = 2 into x³ − 2x − 5 term by term.''", "inputs": null, "expected": null}, {"name": "test_nr_df_x0", "description": "Step 2: f′(x₀)", "hidden": false, "code": "assert near(answer(''nr_df0'', ''f′(x₀)''), 10.0, 1e-06), ''Differentiate f(x) first using the power rule, then substitute x₀ = 2.''", "inputs": null, "expected": null}, {"name": "test_nr_x1", "description": "Step 3: x₁", "hidden": false, "code": "assert near(answer(''nr_x1'', ''x₁ = x₀ − f(x₀) / f′(x₀)''), 2.1, 0.0001), ''Apply the update x₁ = x₀ − f(x₀) / f′(x₀). Watch the sign when f(x₀) is negative.''", "inputs": null, "expected": null}, {"name": "test_nr_f_x1", "description": "Step 4: f(x₁)", "hidden": false, "code": "assert near(answer(''nr_f1'', ''f(x₁)''), 0.061, 0.0005), ''Evaluate f at your x₁. Keep at least 4 decimal places.''", "inputs": null, "expected": null}, {"name": "test_nr_df_x1", "description": "Step 5: f′(x₁)", "hidden": false, "code": "assert near(answer(''nr_df1'', ''f′(x₁)''), 11.23, 0.005), ''Evaluate the derivative from step 2 at your x₁.''", "inputs": null, "expected": null}, {"name": "test_nr_x2", "description": "Step 6: x₂", "hidden": false, "code": "assert near(answer(''nr_x2'', ''x₂ = x₁ − f(x₁) / f′(x₁)''), 2.094568, 0.0001), ''Apply the same update again, starting from x₁.''", "inputs": null, "expected": null}, {"name": "test_nr_root", "description": "Step 7: the root", "hidden": false, "code": "assert near(answer(''nr_root'', ''Root correct to 4 decimal places''), 2.0945515, 5e-05), ''Iterate until two successive values agree to 4 decimal places, then round.''", "inputs": null, "expected": null}, {"name": "test_sr_h", "description": "Step 1: h", "hidden": false, "code": "assert near(answer(''sr_h'', ''Strip width h''), 0.25, 1e-09), ''h = (b − a) / n, with a = 0, b = 1 and n = 4.''", "inputs": null, "expected": null}, {"name": "test_sr_ends", "description": "Step 2: end ordinates", "hidden": false, "code": "assert near(answer(''sr_ends'', ''y₀ + y₄''), 1.5, 0.0001), ''y₀ = f(0) and y₄ = f(1), where f(x) = 1 / (1 + x²).''", "inputs": null, "expected": null}, {"name": "test_sr_odd", "description": "Step 3: odd ordinates", "hidden": false, "code": "assert near(answer(''sr_odd'', ''4 × (y₁ + y₃)''), 6.324706, 0.0005), ''The odd ordinates are y₁ = f(0.25) and y₃ = f(0.75). Add them, then multiply by 4.''", "inputs": null, "expected": null}, {"name": "test_sr_even", "description": "Step 4: even ordinate", "hidden": false, "code": "assert near(answer(''sr_even'', ''2 × y₂''), 1.6, 0.0001), ''The even interior ordinate is y₂ = f(0.5). Multiply it by 2.''", "inputs": null, "expected": null}, {"name": "test_sr_integral", "description": "Step 5: the integral", "hidden": false, "code": "assert near(answer(''sr_integral'', ''I ≈ (h / 3) × [(y₀ + y₄) + 4(y₁ + y₃) + 2y₂]''), 0.785392, 5e-05), ''Add the three terms from steps 2–4, then multiply by h / 3.''", "inputs": null, "expected": null}, {"name": "test_sr_pi", "description": "Step 6: estimate of π", "hidden": false, "code": "assert near(answer(''sr_pi'', ''π ≈ 4 × I''), 3.141569, 0.0001), ''The exact value of the integral is π / 4, so multiply your I by 4.''", "inputs": null, "expected": null}]'::jsonb, '[{"id": "correctness", "name": "Correct answers", "description": "Each step''s value is correct.", "max_points": 7.0}, {"id": "precision", "name": "Working and precision", "description": "Every step is answered, to the requested number of decimal places.", "max_points": 3.0}]'::jsonb, 10.0, now() + interval '194400 seconds', 'published', true, 'off', NULL, NULL, '{"kind": "problems", "apparatus": null, "apparatus_config": {}, "table": null, "graph": null, "sections": [{"id": "newton", "title": "Problem 1 · Newton–Raphson method", "body": "Find the real root of **f(x) = x³ − 2x − 5**, starting from **x₀ = 2**.", "visual": "newton", "steps": [{"id": "nr_f0", "label": "f(x₀)", "unit": "", "placeholder": "", "test": "test_nr_f_x0"}, {"id": "nr_df0", "label": "f′(x₀)", "unit": "", "placeholder": "", "test": "test_nr_df_x0"}, {"id": "nr_x1", "label": "x₁ = x₀ − f(x₀) / f′(x₀)", "unit": "", "placeholder": "", "test": "test_nr_x1"}, {"id": "nr_f1", "label": "f(x₁)", "unit": "", "placeholder": "4 decimal places", "test": "test_nr_f_x1"}, {"id": "nr_df1", "label": "f′(x₁)", "unit": "", "placeholder": "", "test": "test_nr_df_x1"}, {"id": "nr_x2", "label": "x₂ = x₁ − f(x₁) / f′(x₁)", "unit": "", "placeholder": "4 decimal places", "test": "test_nr_x2"}, {"id": "nr_root", "label": "Root correct to 4 decimal places", "unit": "", "placeholder": "4 decimal places", "test": "test_nr_root"}]}, {"id": "simpson", "title": "Problem 2 · Simpson''s 1/3 rule", "body": "Estimate **I = ∫₀¹ dx / (1 + x²)** using **n = 4** strips. The exact value is π / 4, so your result also estimates π.", "visual": "simpson", "steps": [{"id": "sr_h", "label": "Strip width h", "unit": "", "placeholder": "", "test": "test_sr_h"}, {"id": "sr_ends", "label": "y₀ + y₄", "unit": "", "placeholder": "", "test": "test_sr_ends"}, {"id": "sr_odd", "label": "4 × (y₁ + y₃)", "unit": "", "placeholder": "4 decimal places", "test": "test_sr_odd"}, {"id": "sr_even", "label": "2 × y₂", "unit": "", "placeholder": "", "test": "test_sr_even"}, {"id": "sr_integral", "label": "I ≈ (h / 3) × [(y₀ + y₄) + 4(y₁ + y₃) + 2y₂]", "unit": "", "placeholder": "4 decimal places", "test": "test_sr_integral"}, {"id": "sr_pi", "label": "π ≈ 4 × I", "unit": "", "placeholder": "4 decimal places", "test": "test_sr_pi"}]}]}'::jsonb, '6b47723e-78f6-53d1-ac62-a2f44c997dc7', now() - interval '691200 seconds', now() - interval '691200 seconds'),
  ('b3ae4a3b-bdd6-5898-9ba5-dd4d4204617a', '423d86b2-49eb-5752-92b1-ef290716e204', 'Lab 1: Simple Pendulum — Measuring g', '## Lab 1: Simple Pendulum — Measuring g

**Aim.** Find the acceleration due to gravity, *g*, from the period of a simple pendulum.

**Theory.** For small swings the period is T = 2π √(L / g), so **T² = (4π² / g) · L**. A graph of T² against L is a
straight line through the origin with slope 4π² / g.

**Procedure** (in the **Worksheet** tab)
1. Set the length L with the slider and press **Time 10 oscillations**. The stopwatch stops after 10 full swings.
2. Press **Record reading** to copy L and t₁₀ into the observation table. Take **at least 5 readings** spread over
   **0.4 m or more**.
3. Fill in T = t₁₀ / 10 and T² for each row. The graph of T² against L draws itself as you go.
4. Find the slope from the best-fit line, then g = 4π² / slope, and the percentage error against 9.81 m/s².

Press **Check** at any time to see which parts are right.
', 'worksheet', 'worksheet', '{"answers.json": "{\"steps\": {}, \"rows\": []}"}'::jsonb, '[{"name": "test_readings", "description": "At least 5 readings at different lengths, spread over 0.4 m or more.", "hidden": false, "code": "readings(5)\nL = column(\"L\", \"Length\")\nassert len(set(round(x, 3) for x in L)) >= 5, \"Take readings at 5 different lengths (some of yours repeat)\"\nassert max(L) - min(L) >= 0.4 - 1e-9, \"Spread your lengths over at least 0.4 m so the graph is reliable\"", "inputs": null, "expected": null}, {"name": "test_periods", "description": "T is the period of one oscillation for every reading.", "hidden": false, "code": "t10 = column(\"t10\", \"t10\")\nT = column(\"T\", \"Period T\")\nfor i, (a, b) in enumerate(zip(T, t10)):\n    assert near(a, b / 10, 0.0051), \"Reading %d: T is the time for ONE oscillation, but you timed 10\" % (i + 1)", "inputs": null, "expected": null}, {"name": "test_t_squared", "description": "T² is the square of T for every reading.", "hidden": false, "code": "T = column(\"T\", \"Period T\")\nT2 = column(\"T2\", \"T squared\")\nfor i, (a, b) in enumerate(zip(T2, T)):\n    assert near_rel(a, b * b, 0.01), \"Reading %d: T² should be your T multiplied by itself\" % (i + 1)", "inputs": null, "expected": null}, {"name": "test_slope", "description": "The slope matches the best-fit line of your T²–L graph.", "hidden": false, "code": "m, _ = fit_line(column(\"L\", \"Length\"), column(\"T2\", \"T squared\"))\ns = answer(\"slope\", \"Slope\")\nassert near_rel(s, m, 0.03), \"The slope doesn''t match your graph. Use two points far apart on the line: (T² change) / (L change)\"", "inputs": null, "expected": null}, {"name": "test_g_value", "description": "g follows from your slope and is physically reasonable.", "hidden": false, "code": "s = answer(\"slope\", \"Slope\")\ng = answer(\"g\", \"g\")\nassert s > 0, \"The slope of T² against L must be positive\"\nassert near_rel(g, 4 * math.pi ** 2 / s, 0.01), \"g should follow from your slope, g = 4π² / slope\"\nassert 9.3 <= g <= 10.3, \"g = %.2f m/s² is far from 9.81 m/s². Recheck your readings and slope\" % g", "inputs": null, "expected": null}, {"name": "test_percent_error", "description": "Percentage error against 9.81 m/s².", "hidden": false, "code": "g = answer(\"g\", \"g\")\npe = answer(\"percent_error\", \"Percentage error\")\nassert near(pe, abs(g - 9.81) / 9.81 * 100, 0.06), \"Percentage error = |g − 9.81| / 9.81 × 100, using your g\"", "inputs": null, "expected": null}, {"name": "test_readings_genuine", "description": "Readings come from the apparatus.", "hidden": true, "code": "for i, (L, t10) in enumerate(zip(column(\"L\"), column(\"t10\"))):\n    assert near_rel(t10, 20 * math.pi * math.sqrt(L / 9.81), 0.03), \"Reading %d does not match the apparatus\" % (i + 1)", "inputs": null, "expected": null}]'::jsonb, '[{"id": "correctness", "name": "Calculations and result", "description": "Every calculated column and step is correct.", "max_points": 6.0}, {"id": "observations", "name": "Observations", "description": "At least five readings over a good range, taken from the apparatus.", "max_points": 2.0}, {"id": "precision", "name": "Units and precision", "description": "Values are given with sensible precision.", "max_points": 2.0}]'::jsonb, 10.0, now() - interval '324000 seconds', 'published', true, 'off', NULL, NULL, '{"kind": "experiment", "apparatus": "pendulum", "apparatus_config": {"g": 9.81, "min_length_m": 0.2, "max_length_m": 1.2}, "table": {"title": "Observation table", "columns": [{"key": "L", "label": "Length L", "unit": "m", "source": "apparatus", "test": null}, {"key": "t10", "label": "Time for 10 oscillations t₁₀", "unit": "s", "source": "apparatus", "test": null}, {"key": "T", "label": "Period T = t₁₀ / 10", "unit": "s", "source": "student", "test": "test_periods"}, {"key": "T2", "label": "T²", "unit": "s²", "source": "student", "test": "test_t_squared"}], "min_rows": 5, "max_rows": 10, "test": "test_readings"}, "graph": {"title": "T² against L", "x": "L", "y": "T2", "x_label": "L (m)", "y_label": "T² (s²)"}, "sections": [{"id": "analysis", "title": "Calculations", "body": "Read the slope from two points far apart on the best-fit line.", "visual": null, "steps": [{"id": "slope", "label": "Slope of the T²–L graph", "unit": "s²/m", "placeholder": "", "test": "test_slope"}, {"id": "g", "label": "g = 4π² / slope", "unit": "m/s²", "placeholder": "2 decimal places", "test": "test_g_value"}, {"id": "percent_error", "label": "Percentage error = |g − 9.81| / 9.81 × 100", "unit": "%", "placeholder": "", "test": "test_percent_error"}]}]}'::jsonb, 'b11e4eb9-ff55-55d9-9240-b1320215a9e2', now() - interval '1555200 seconds', now() - interval '1555200 seconds')
